import{_ as a,o as r,c as o,a2 as s}from"./chunks/framework.BjkiRu3Q.js";const t="/images/cliente/carrito-drawer.png",g=JSON.parse('{"title":"5. El Carrito de Compras y Cupones de Descuento","description":"","frontmatter":{},"headers":[],"relativePath":"cliente/carrito.md","filePath":"cliente/carrito.md"}'),i={name:"cliente/carrito.md"};function n(l,e,c,d,u,p){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="_5-el-carrito-de-compras-y-cupones-de-descuento" tabindex="-1">5. El Carrito de Compras y Cupones de Descuento <a class="header-anchor" href="#_5-el-carrito-de-compras-y-cupones-de-descuento" aria-label="Permalink to &quot;5. El Carrito de Compras y Cupones de Descuento&quot;">​</a></h1><p>El carrito de compras es tu bolsa virtual. Puedes abrirlo en cualquier momento desde el botón superior de la tienda para revisar tus artículos seleccionados, cambiar cantidades o aplicar un código de descuento promocional.</p><hr><h2 id="_5-1-abrir-y-usar-el-carrito-lateral" tabindex="-1">5.1 Abrir y Usar el Carrito Lateral <a class="header-anchor" href="#_5-1-abrir-y-usar-el-carrito-lateral" aria-label="Permalink to &quot;5.1 Abrir y Usar el Carrito Lateral&quot;">​</a></h2><p>Cada vez que agregas un producto desde el catálogo o la ficha detallada, se despliega una ventana lateral desde el borde derecho sin interrumpir tu navegación ni sacarte de la página en la que te encuentras:</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Ventana Lateral del Carrito de Compras</span><span class="screenshot-url">https://pyme.rsfsecure.site/ (abrir carrito)</span></div><div class="screenshot-body"><img src="'+t+'" alt="Ventana Lateral del Carrito de Compras"></div></div><h3 id="que-puedes-hacer-dentro-del-carrito" tabindex="-1">Qué puedes hacer dentro del carrito: <a class="header-anchor" href="#que-puedes-hacer-dentro-del-carrito" aria-label="Permalink to &quot;Qué puedes hacer dentro del carrito:&quot;">​</a></h3><ul><li><strong>Modificar cantidades:</strong> Usa los botones <code>+</code> y <code>-</code> junto a cada artículo para sumar o restar unidades. El subtotal y los impuestos se actualizarán al instante.</li><li><strong>Eliminar un artículo:</strong> Si decidiste no llevar un producto, haz clic en el icono de cesto o en el botón &quot;Eliminar&quot;. El artículo saldrá de tu bolsa sin afectar los demás.</li><li><strong>Barra de Progreso para Envío Gratis:</strong> Si la tienda tiene activa una promoción de flete sin costo a partir de un monto determinado (ejemplo: <em>$75.00</em>), verás una barra que te indica exactamente cuántos dólares te faltan para conseguir el envío completamente gratis.</li><li><strong>Desglose de Totales:</strong> Podrás ver claramente el subtotal de mercancía y el <strong>7% de ITBMS</strong> correspondiente por ley en Panamá antes de pasar a la caja.</li><li><strong>Seguir mirando artículos:</strong> Haz clic fuera del panel o en la cruz <code>X</code> superior para cerrarlo. Tus artículos permanecerán guardados en tu bolsa de compras aunque cambies de página o apagues tu dispositivo.</li></ul><hr><h2 id="_5-2-como-aplicar-un-cupon-de-descuento" tabindex="-1">5.2 Cómo Aplicar un Cupón de Descuento <a class="header-anchor" href="#_5-2-como-aplicar-un-cupon-de-descuento" aria-label="Permalink to &quot;5.2 Cómo Aplicar un Cupón de Descuento&quot;">​</a></h2><p>Si recibiste un código promocional por nuestras redes sociales, boletín de correo o WhatsApp (por ejemplo: <code>BIENVENIDA</code>, <code>BLACKFRIDAY</code> o <code>VERANO2026</code>):</p><ol><li>Abre el carrito de compras.</li><li>Localiza la casilla de texto <strong>&quot;¿Tienes un cupón de descuento?&quot;</strong>.</li><li>Escribe el código respetando letras mayúsculas y sin dejar espacios antes ni después.</li><li>Presiona el botón verde <strong>&quot;Aplicar&quot;</strong>.</li><li>Verás el descuento reflejado inmediatamente en color verde restándose del valor total de la orden.</li></ol><h3 id="¿que-hacer-si-el-cupon-muestra-un-aviso-de-error" tabindex="-1">¿Qué hacer si el cupón muestra un aviso de error? <a class="header-anchor" href="#¿que-hacer-si-el-cupon-muestra-un-aviso-de-error" aria-label="Permalink to &quot;¿Qué hacer si el cupón muestra un aviso de error?&quot;">​</a></h3><ul><li><strong>&quot;El cupón no existe o ha expirado&quot;:</strong> Revisa que esté bien escrito o verifica la fecha límite de validez de la promoción.</li><li><strong>&quot;No alcanzas el monto mínimo de compra&quot;:</strong> Algunos cupones aplican únicamente si tu pedido supera cierto valor (ejemplo: compras mayores a <em>$30.00</em>). Agrega otro artículo al carrito para alcanzar el beneficio.</li><li><strong>&quot;El cupón ya alcanzó el límite de usos&quot;:</strong> Algunas ofertas especiales son válidas exclusivamente para los primeros 50 o 100 compradores.</li></ul><hr><h2 id="_5-3-preguntas-frecuentes-sobre-el-carrito" tabindex="-1">5.3 Preguntas Frecuentes sobre el Carrito <a class="header-anchor" href="#_5-3-preguntas-frecuentes-sobre-el-carrito" aria-label="Permalink to &quot;5.3 Preguntas Frecuentes sobre el Carrito&quot;">​</a></h2><details class="details custom-block"><summary>¿Se apartan los artículos cuando los agrego al carrito?</summary><p>Agregar un producto al carrito no reserva su inventario de forma indefinida. Para garantizar que nadie más compre la última unidad disponible, te recomendamos completar el checkout y realizar el pago.</p></details><details class="details custom-block"><summary>¿Puedo aplicar dos cupones de descuento en el mismo pedido?</summary><p>El sistema permite aplicar un cupón por cada compra realizada. Si tienes más de un código, elige el que te brinde el mayor beneficio o utilízalo en tu siguiente pedido.</p></details>',18)])])}const h=a(i,[["render",n]]);export{g as __pageData,h as default};
